// Demo: Signature Canvas Fingerprint Poisoning — per-session noise makes the fingerprint unstable
function hash(s){var h=2166136261;for(var i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return (h>>>0).toString(16);}
var base='signal-1-2';var sessions=[];
for(var s=0;s<3;s++){sessions.push(hash(base+'|salt-'+(s*7919+1)));}
console.log('technique: Signature Canvas Fingerprint Poisoning');
sessions.forEach(function(h,i){console.log('session '+(i+1)+' fingerprint: '+h);});
console.log(sessions[0]!==sessions[1]&&sessions[1]!==sessions[2]?'result: fingerprints differ per session — tracking broken':'result: STABLE (countermeasure failed)');

// Demo: Signature User-Agent Client Hints Reduction — odd raw values collapse into common buckets
function bucket(v){var b=[800,1024,1280,1366,1440,1536,1600,1920,2560];for(var i=0;i<b.length;i++){if(v<=b[i])return b[i];}return 2560;}
var samples=[];for(var i=0;i<10;i++){samples.push(700+((i*53+2)%2000));}
var mapped=samples.map(bucket);var uniq={};mapped.forEach(function(v){uniq[v]=1;});
console.log('technique: Signature User-Agent Client Hints Reduction');
console.log('raw distinct values: '+samples.length+' -> buckets used: '+Object.keys(uniq).length);
console.log('bucket set: '+Object.keys(uniq).join(', '));

// Demo: Signature WebGL Renderer String Masking — fingerprint entropy before vs after the countermeasure
function shannon(counts){var tot=counts.reduce(function(a,b){return a+b;},0);var h=0;counts.forEach(function(c){if(c>0){var p=c/tot;h-=p*Math.log2(p);}});return h;}
var before=[],after=[];for(var i=0;i<15;i++){before.push(1+((i*37+3)%5));after.push(1+((i*13)%2));}
var hb=shannon(before),ha=shannon(after);
console.log('technique: Signature WebGL Renderer String Masking');console.log('signals sampled: '+15);
console.log('entropy before: '+hb.toFixed(2)+' bits');console.log('entropy after:  '+ha.toFixed(2)+' bits');
console.log('reduction: '+(hb-ha).toFixed(2)+' bits — the fingerprint is far less identifying');

